class Bag {
    protected final List<String> items = new ArrayList<>();
    void add(String s) { items.add(s); }
    void addAll(List<String> all) {
        for (String s : all) add(s);
    }
}

class CountingBag extends Bag {
    int count = 0;
    @Override void add(String s) { count++; super.add(s); }
    @Override void addAll(List<String> all) {
        count += all.size();
        super.addAll(all);
    }
}

CountingBag bag = new CountingBag();
bag.addAll(List.of("a", "b", "c"));
System.out.println(bag.count);

